 {full&&tab.startsWith('prop-chart-')&&<AccountingChartScreen db={db} title={(PROPERTY_CHART_ITEMS.find(x=>x[0]===tab)||['',tab])[1]} chartKey={tab.replace('prop-chart-','').replace('debtors','debtors').replace('collection','collection').replace('billing','billing').replace('aging','aging')}/>}
 {full&&(tab.startsWith('prop-tx-')||tab.startsWith('fin-'))&&<AccountingModule tab={tab} db={db} update={update} user={user}/>}
 {tab==='property-tenancy'&&full&&<PropertyTenancy db={db} update={update} user={user}/>}
 {tab==='property-ownership'&&full&&<PropertyOwnership db={db} update={update} user={user}/>}
 {tab==='property-transactions'&&full&&<PropertyTransactions db={db} update={update} user={user}/>}
 {tab==='property-summary'&&full&&<PropertySummary db={db}/>}
 {tab==='maintenance-defects'&&(full||resident||technical)&&<MaintenanceDefects db={db} update={update} user={user}/>}
 {tab==='contractors'&&(full||technical)&&<Contractors db={db} update={update} user={user}/>}
 {tab==='general-ledger'&&full&&<GeneralLedger db={db} update={update} user={user}/>}
 {tab==='cash-book'&&full&&<CashBook db={db} update={update} user={user}/>}
 {tab==='pending'&&full&&<Applications db={db} update={update} user={user} pendingOnly/>}
 {tab==='today'&&full&&<FinancialDashboard db={db} update={update} user={user}/>} 
 {tab==='ledger'&&full&&<Ledger db={db} update={update} user={user}/>} 
 {tab==='applications'&&full&&<Applications db={db} update={update} user={user}/>} 
 {tab==='monthly-invoice'&&resident&&<MonthlyInvoice db={db} user={user}/>}
 {tab==='management-payment'&&<ManagementPayment db={db} update={update} user={user}/>}
 {tab==='defaulters-installments'&&(full||resident)&&<DefaultersInstallments db={db} update={update} user={user}/>}{tab==='access-cards'&&(full||resident)&&<AccessCards db={db} update={update} user={user}/>}
 {tab==='overnight-parking'&&<OvernightParking db={db} update={update} user={user}/>}
 {tab==='visitor-registration'&&<VisitorRegistration db={db} update={update} user={user}/>}
 {tab==='security-incident-report'&&(guard||full)&&<SecurityIncidentReport db={db} update={update} user={user}/>} 
 {tab==='reports'&&full&&<Reports db={db}/>} 
