function purgeExpiredDeleted(d){
 const now=Date.now(); const thirty=30*24*60*60*1000;
 d.deletedRecords=Array.isArray(d.deletedRecords)?d.deletedRecords:[];
 d.deletedRecords=d.deletedRecords.filter(x=>now-new Date(x.deletedAt||0).getTime()<thirty);
 return d;
}
function softDelete(d,arrayName,id,user,action,label){
 const arr=Array.isArray(d[arrayName])?d[arrayName]:[]; const i=arr.findIndex(x=>x.id===id); if(i<0)return false;
 const row=structuredClone(arr[i]); row.deletedAt=new Date().toISOString(); row.permanentDeleteAfter=new Date(Date.now()+30*24*60*60*1000).toISOString(); row.deletedBy=user?.id||'SYSTEM'; row.deletedByName=user?.name||user?.id||'System';
 d.deletedRecords=Array.isArray(d.deletedRecords)?d.deletedRecords:[]; d.deletedRecords.unshift({id:uid(),source:arrayName,recordId:id,label:label||id,deletedAt:row.deletedAt,permanentDeleteAfter:row.permanentDeleteAfter,deletedBy:row.deletedBy,deletedByName:row.deletedByName,data:row});
 d[arrayName]=arr.filter(x=>x.id!==id); auditLog(d,user,action||'SOFT_DELETE',`${label||id} — retained for 30 days before permanent deletion`); return true;
}
function auditLog(d,user,action,detail){d.audit.unshift({id:uid(),at:new Date().toISOString(),by:user?.id||'SYSTEM',byName:user?.name||user?.id||'System',action,detail});}
function ModuleMenu({title,subtitle,items,go}){return <><div className="page-title"><div><h2>{title}</h2><p>{subtitle}</p></div></div><div className="module-grid">{items.map(x=><button key={x.tab} className="module-card" onClick={()=>go(x.tab)}><span>{x.icon}</span><b>{x.label}</b><small>{x.desc}</small><em>Open →</em></button>)}</div></>}

