function PropertySummary({db}){const activeTen=db.propertyTenancies.filter(x=>x.status==='Active').length;const owners=new Set(db.propertyOwnerships.map(x=>x.unit)).size;const units=new Set([...db.propertyTenancies.map(x=>x.unit),...db.propertyOwnerships.map(x=>x.unit),...db.propertyTransactions.map(x=>x.unit)].filter(Boolean)).size;const value=db.propertyTransactions.reduce((n,x)=>n+Number(x.amount||0),0);const rows=db.propertyTransactions.map(x=>({Date:x.date||'',Unit:x.unit||'',Type:x.transactionType||'',Reference:x.referenceNo||'',Party:x.party||'',Amount:Number(x.amount||0),Status:x.status||'',ProcessedBy:x.processedBy||''}));return <><div className="page-title"><div><h2>Property Summary Report</h2><p>Current property management overview.</p></div><ExportButtons title="Property-Summary" rows={rows}/></div><div className="cards"><Card title="Units With Records" value={units}/><Card title="Active Tenancies" value={activeTen}/><Card title="Units With Owners" value={owners}/><Card title="Property Transactions" value={db.propertyTransactions.length}/><Card title="Transaction Value" value={money(value)}/></div><Panel title="Recent Property Transactions"><div className="tablewrap"><table><thead><tr><th>Date</th><th>Unit</th><th>Type</th><th>Reference</th><th>Amount</th><th>Status</th></tr></thead><tbody>{db.propertyTransactions.slice(0,20).map(x=><tr key={x.id}><td>{fmtDate(x.date)}</td><td>{x.unit}</td><td>{x.transactionType}</td><td>{x.referenceNo||'-'}</td><td>{money(x.amount)}</td><td>{x.status}</td></tr>)}</tbody></table></div></Panel></>}
