function purgeExpiredVisitorLogs(d){const cutoff=Date.now()-90*24*60*60*1000;d.visitorLogs=Array.isArray(d.visitorLogs)?d.visitorLogs:[];d.visitorLogs=d.visitorLogs.filter(x=>new Date(x.at||0).getTime()>=cutoff);return d;}
function visitorUnitFor(user,db){if(!user)return '';if(user.role==='Tenant'){const parent=db.users.find(u=>u.id===user.parentResidentId||u.id===user.residentId);return parent?.unitNo||parent?.id||user.unitNo||'';}return user.unitNo||user.id||'';}
