 const logs=(db.visitorLogs||[]).filter(l=>selected&&l.registrationId===selected.id);const exportRows=(resident?db.visitorRegistrations.filter(v=>v.residentId===profile.residentId||v.unit===profile.unit):db.visitorRegistrations).map(v=>({PassNo:v.passNo,Unit:v.unit,Resident:v.residentName,Visitor:v.visitorName,Contact:v.visitorContact,Vehicle:v.carPlate||'',From:v.fromDate,Until:v.toDate,Overnight:v.overnight?'Yes':'No',Status:v.status||'Active'}));
