function titlify(title){return String(title||'REPORT').replace(/[-_]+/g,' ').replace(/\b\w/g,m=>m.toUpperCase())}
function makeProfessionalFormPdf(filename,html,title){
 const clean=s=>String(s??'').replace(/<br\s*\/?>(?=\s*)/gi,' | ').replace(/<[^>]+>/g,'').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/\s+/g,' ').trim();
 const isSchedule=/INSTALLMENT PAYMENT SCHEDULE/i.test(title);
 if(isSchedule){
   const headMatch=String(html).match(/<thead>[\s\S]*?<tr>([\s\S]*?)<\/tr>[\s\S]*?<\/thead>/i);
   const headers=headMatch?[...headMatch[1].matchAll(/<th[^>]*>([\s\S]*?)<\/th>/gi)].map(m=>clean(m[1])):[];
   const bodyMatch=String(html).match(/<tbody>([\s\S]*?)<\/tbody>/i);
   const bodyRows=bodyMatch?[...bodyMatch[1].matchAll(/<tr[^>]*>([\s\S]*?)<\/tr>/gi)].map(m=>[...m[1].matchAll(/<td[^>]*>([\s\S]*?)<\/td>/gi)].map(x=>clean(x[1]))).filter(r=>r.length):[];
   const objects=bodyRows.map(r=>Object.fromEntries(r.map((v,i)=>[headers[i]||`Column ${i+1}`,v])));
   return makeStyledDataPdf(filename,title,objects.length?objects:[{REPORT:'No schedule records found'}],'schedule');
 }
 const fields=[...String(html).matchAll(/<tr>\s*<th[^>]*>([\s\S]*?)<\/th>\s*<td[^>]*>([\s\S]*?)<\/td>\s*<\/tr>/gi)].map(m=>({Field:clean(m[1]),Value:clean(m[2])}));
 return makeStyledDataPdf(filename,title,fields.length?fields:[{Field:'Report',Value:'No records found'}],'form');
}
