    {staff&&<Panel title="Overnight Parking Quick Actions"><div className="seg"><button className={view==='queue'?'sel':''} onClick={()=>setView('queue')}>APPLICATIONS</button><button className={view==='lots'?'sel':''} onClick={()=>setView('lots')}>PARKING LOTS</button><button className={view==='blacklist'?'sel':''} onClick={()=>setView('blacklist')}>BLACKLISTED</button></div></Panel>}
    {create&&<OvernightForm db={db} update={update} user={user} editApp={null} onClose={()=>setCreate(false)} onCreated={()=>setCreate(false)}/>} 
    {edit&&<OvernightForm db={db} update={update} user={user} editApp={edit} onClose={()=>setEditId(null)} onCreated={()=>setEditId(null)}/>} 
