function AccountingModule({tab,db,update,user}){
 const prop=tab.startsWith('prop-tx-');
 if(prop){const item=PROPERTY_TX_ITEMS.find(x=>x[0]===tab);if(tab==='prop-tx-official-receipt')return <CashBook db={db} update={update} user={user}/>;if(tab==='prop-tx-advance-setting')return <AccountingDocumentEntry db={db} update={update} user={user} title={item?.[1]||'Advance Payment Setting'} docType="Advance Payment Setting"/>;return <AccountingDocumentEntry db={db} update={update} user={user} title={item?.[1]||'Accounting Transaction'} docType={item?.[1]||'Accounting Transaction'}/>}
 const cfg=FINANCIAL_GROUPS.flatMap(g=>g.items).find(x=>x[0]===tab);const title=cfg?.[1]||'Financial Accounting';const kind=cfg?.[2];
 if(kind==='receipt')return <CashBook db={db} update={update} user={user}/>;
 if(kind==='recon')return <BankReconciliation db={db} update={update} user={user}/>;
 if(kind==='budget')return <BudgetScreen db={db} update={update} user={user} title={title} kind={tab.includes('sinking')?'sinking':tab.includes('service')?'service':'general'}/>;
 if(kind==='report'){
   const map={'fin-gl-audit':'audit-list','fin-gl-listing':'transaction-summary','fin-gl-doc':'document-query','fin-cb-control':'cash-bank','fin-fs-trial':'trial-balance','fin-fs-balance':'balance-sheet','fin-fs-receipts':'receives-payments','fin-fs-comparison':'accounts-comparison','fin-fs-fund':'fund-statement','fin-fs-period':'period-analysis','fin-ar-ledger':'ar-ledger','fin-ar-outstanding':'ar-outstanding','fin-ar-aging':'ar-aging','fin-ap-ledger':'ap-ledger','fin-ap-outstanding':'ap-outstanding','fin-ap-aging':'ap-aging'};return <AccountingReportScreen db={db} title={title} reportKey={map[tab]||'transaction-summary'}/>;
 }
 return <AccountingDocumentEntry db={db} update={update} user={user} title={title} docType={title}/>;
}

